const axios = require('axios');
const qs = require('qs');

axios.post('https://uat.digitalrakshak.io/v1/oauth/token', qs.stringify({ grant_type: 'client_credentials' }), {
  headers: {
    'Authorization': 'Bearer <API_SECRET>',
    'Content-Type': 'application/x-www-form-urlencoded'
